fn poll_acp_startup(&mut self, context: &egui::Context) {
    let Some(pending) = self.acp_startup.as_ref() else {
        return;
    };
    if let Some(progress) = pending.task.latest_progress() {
        self.status = Some(progress);
    }
    let Some(result) = pending.task.poll() else {
        context.request_repaint_after(std::time::Duration::from_millis(50));
        return;
    };
    let Some(pending) = self.acp_startup.take() else {
        return;
    };
    let continuation = pending.continuation;
    let mut started = match result {
        Ok(started) => started,
        Err(error) => {
            match continuation {
                AcpStartupContinuation::Ask {
                    gameengine_session_id,
                    ..
                } => {
                    let diagnostic = format!("ACP Ask startup failed: {error}");
                    self.status = Some(diagnostic.clone());
                    let _ = self.host.append_message(
                        &gameengine_session_id,
                        ConversationRole::System,
                        diagnostic,
                    );
                }
                AcpStartupContinuation::Build { run_id, .. } => {
                    let diagnostic = format!("ACP Build startup failed: {error}");
                    if self
                        .host
                        .run(&run_id)
                        .is_ok_and(|run| !run.state.is_terminal())
                    {
                        self.fail_run(&run_id, diagnostic);
                    } else {
                        self.status = Some(diagnostic);
                    }
                }
            }
            return;
        }
    };

    let expected_agent_id = match &continuation {
        AcpStartupContinuation::Ask { agent_id, .. }
        | AcpStartupContinuation::Build { agent_id, .. } => agent_id.as_str(),
    };
    let descriptor_id = started.runtime.descriptor().id.clone();
    if descriptor_id != expected_agent_id {
        let _ = started.session.cancel();
        let _ = started.session.close();
        let diagnostic = format!(
            "ACP startup returned descriptor `{descriptor_id}` while `{expected_agent_id}` was requested."
        );
        match continuation {
            AcpStartupContinuation::Ask {
                gameengine_session_id,
                ..
            } => {
                let _ = self.host.append_message(
                    &gameengine_session_id,
                    ConversationRole::System,
                    diagnostic.clone(),
                );
                self.status = Some(diagnostic);
            }
            AcpStartupContinuation::Build { run_id, .. } => {
                self.fail_run(&run_id, diagnostic);
            }
        }
        return;
    }
    if let Err(error) = self.acp.replace(started.runtime) {
        let _ = started.session.cancel();
        let _ = started.session.close();
        let diagnostic = format!("Could not register started ACP runtime: {error}");
        match continuation {
            AcpStartupContinuation::Ask {
                gameengine_session_id,
                ..
            } => {
                let _ = self.host.append_message(
                    &gameengine_session_id,
                    ConversationRole::System,
                    diagnostic.clone(),
                );
                self.status = Some(diagnostic);
            }
            AcpStartupContinuation::Build { run_id, .. } => {
                self.fail_run(&run_id, diagnostic);
            }
        }
        return;
    }
    self.execution_router.sync_registry(self.acp.registry());

    match continuation {
        AcpStartupContinuation::Ask {
            gameengine_session_id,
            prompt,
            ..
        } => {
            let acp_session_id = match self.acp.attach_opened_ask_session(
                &self.host,
                descriptor_id,
                started.session,
                &gameengine_session_id,
            ) {
                Ok(session_id) => session_id,
                Err(error) => {
                    let diagnostic = format!("Could not attach ACP Ask session: {error}");
                    self.status = Some(diagnostic.clone());
                    let _ = self.host.append_message(
                        &gameengine_session_id,
                        ConversationRole::System,
                        diagnostic,
                    );
                    return;
                }
            };
            if let Err(error) =
                self.acp
                    .send_prompt(&mut self.host, &acp_session_id, &prompt)
            {
                let _ = self.acp.close_session(&acp_session_id);
                let diagnostic = format!("Could not send ACP Ask prompt: {error}");
                self.status = Some(diagnostic.clone());
                let _ = self.host.append_message(
                    &gameengine_session_id,
                    ConversationRole::System,
                    diagnostic,
                );
                return;
            }
            self.acp_question = Some(AcpQuestionState {
                acp_session_id,
                gameengine_session_id,
                answer: String::new(),
                started_at: std::time::Instant::now(),
            });
            self.status = Some("Waiting for agent…".to_owned());
        }
        AcpStartupContinuation::Build {
            gameengine_session_id,
            run_id,
            prompt,
            workspace,
            ..
        } => {
            if self
                .host
                .run(&run_id)
                .is_err_or(|run| run.state.is_terminal())
            {
                let _ = started.session.cancel();
                let _ = started.session.close();
                return;
            }
            let acp_session_id = match self.acp.attach_opened_run_session(
                &mut self.host,
                descriptor_id,
                started.session,
                &gameengine_session_id,
                &run_id,
            ) {
                Ok(session_id) => session_id,
                Err(error) => {
                    self.fail_run(
                        &run_id,
                        format!("Could not attach ACP Build session: {error}"),
                    );
                    return;
                }
            };
            let runtime_identity = match self.acp.runtime_identity(&acp_session_id) {
                Ok(identity) => identity,
                Err(error) => {
                    let _ = self.acp.close_session(&acp_session_id);
                    let message =
                        format!("Could not read negotiated ACP runtime identity: {error}");
                    self.fail_run(&run_id, message.clone());
                    if self.benchmark_child_active() {
                        self.write_benchmark_child_failure(
                            BenchmarkRunFailureKind::Harness,
                            message,
                        );
                    }
                    return;
                }
            };
            if let Err(error) = self.validate_benchmark_acp_runtime_identity(&runtime_identity) {
                let _ = self.acp.close_session(&acp_session_id);
                let message = format!("ACP benchmark runtime mismatch: {error}");
                self.fail_run(&run_id, message.clone());
                if self.benchmark_child_active() {
                    self.write_benchmark_child_failure(
                        BenchmarkRunFailureKind::Harness,
                        message,
                    );
                }
                return;
            }
            if let Err(error) =
                self.acp
                    .send_prompt(&mut self.host, &acp_session_id, &prompt)
            {
                let _ = self.acp.close_session(&acp_session_id);
                self.fail_run(&run_id, format!("Could not send ACP Build prompt: {error}"));
                return;
            }
            self.code_workspace = Some(workspace);
            self.active_acp_run_session = Some(acp_session_id);
            if let Err(error) = self.host.transition_run(
                &run_id,
                AgentRunState::Executing,
                "ACP external agent runtime started in the isolated code workspace.",
            ) {
                self.status = Some(error.to_string());
            } else {
                self.status = Some("Waiting for agent…".to_owned());
            }
        }
    }
}

